function applyFoliageMigration(v,legacy={}){
  if(!('foliageFX' in legacy))v.foliageFX=legacy.grassFX!==false;
  if(!('foliageQuality' in legacy))v.foliageQuality=Math.max(0,Math.min(3,Math.round(Number(legacy.grassQuality??3)||0)));
  if(!('foliageWindStrength' in legacy))v.foliageWindStrength=Number.isFinite(Number(legacy.grassWindStrength))?Number(legacy.grassWindStrength):.78;
  if(!('foliageWindSpeed' in legacy))v.foliageWindSpeed=Number.isFinite(Number(legacy.grassWindSpeed))?Number(legacy.grassWindSpeed):.82;
  if(!('foliageInteractionStrength' in legacy))v.foliageInteractionStrength=Number.isFinite(Number(legacy.grassPushStrength))?Number(legacy.grassPushStrength):1.0;
  if(!('foliageBendAmount' in legacy))v.foliageBendAmount=Number.isFinite(Number(legacy.grassHeroStrength))?Number(legacy.grassHeroStrength):1.0;
  if(!('foliageShadingStrength' in legacy))v.foliageShadingStrength=.90;
}
