    this.mothPickups=r.collectibles||r.moth_pickups||[];
    this.decorRobots=r.companions||r.decor_robots||[];
    this.decorLamps=r.decor_lamps||[];
    this.editorDecor=r.editor_decor||[];
    this.decorExclusions=new Set((r.decor_exclusions||[]).map(p=>Array.isArray(p)?p.join(','):String(p)));
    this.patternExclusions=new Set((r.pattern_exclusions||[]).map(String));this.patternDecor=r.pattern_decor||[];
    this.objectFxHidden=new Set((r.object_fx_hidden||[]).map(String));
