      const breath=focus?1+.025*Math.sin(t*2.2):1;this.renderer.add('orb',x,y,w*(focus?1.72:1.34)*breath,h*(focus?1.58:1.24)*breath,g,focus?.12:.07,true);this.renderer.addHD(name,x,y,w,h,.99,false,0,tint);
