      if(focus){this.activeObjectiveMarker={x,y:y,color:g,time:t};if(obj.kind==='rivet')this.renderer.addTop('orb',x,y+2,31,18,this.luts.rgb('fx_objective',205),.12,true);if(obj.kind==='pip')this.renderer.addTop('orb',x,y+2,30,20,this.luts.rgb('fx_teleport',235),.12,true)}oi++
